"The ancient prayer of the Incarnation, prayed at morning, noon, and evening. During the Easter season, the Regina Caeli.": "Starożytna modlitwa o Wcieleniu, odmawiana rano, w południe i wieczorem. W okresie wielkanocnym Regina Caeli.",
