"Keep a private record of your daily prayer, build a steady habit, and see your faithfulness over the weeks.": "Prowadź prywatny zapis codziennej modlitwy, buduj stały nawyk i zobacz swoją wierność na przestrzeni tygodni.",
"Every part of the Mass in order, with when to stand, sit, and kneel, and what each moment means. Follow along on your phone at Mass.": "Każda część Mszy po kolei: kiedy wstać, usiąść i klęknąć oraz co znaczy każda chwila. Śledź ją w telefonie podczas Mszy.",
