"How to become Catholic or come home, the basics of everyday Catholic life, and guides to discerning and living each vocation: marriage, priesthood, religious life, and more.": "Jak zostać katolikiem lub wrócić do Kościoła, podstawy codziennego życia katolika i przewodniki po rozeznawaniu i przeżywaniu każdego powołania: małżeństwa, kapłaństwa, życia zakonnego i innych.",
"The lists every Catholic learns, explained: the Ten Commandments, the Beatitudes, the precepts, the sacraments, the virtues, the works of mercy, the capital sins, and more.": "Wyliczenia, których uczy się każdy katolik, z wyjaśnieniem: Dziesięć Przykazań, Błogosławieństwa, przykazania kościelne, sakramenty, cnoty, uczynki miłosierdzia, grzechy główne i inne.",
"A walk through a Catholic church: what each part is for, the sacred vessels, the vestments, the colors of the seasons, and how to take part in the Mass.": "Spacer po kościele katolickim: do czego służy każda jego część, naczynia liturgiczne, szaty, kolory okresów i jak uczestniczyć we Mszy.",
