"Keep a list of the people and needs you are praying for. When a prayer is answered, mark it and give thanks.": "Zapisuj osoby i sprawy, za które się modlisz. Gdy modlitwa zostanie wysłuchana, zaznacz ją i podziękuj.",
"Tap ☆ Save on any prayer, saint, book, or article to keep it here.": "Dotknij ☆ Zapisz przy dowolnej modlitwie, świętym, książce lub artykule, by mieć je tutaj.",
