"On the crucifix, make the Sign of the Cross and pray the Soul of Christ (Anima Christi).": "Na krzyżyku zrób znak krzyża i odmów Duszo Chrystusowa.",
"On each small bead, pray “Sweet Heart of Jesus, be my love.”": "Na każdym małym paciorku odmów „Najsłodsze Serce Jezusa, bądź moją miłością”.",
"After each group of small beads, pray “Sweet Heart of Mary, be my salvation.”": "Po każdej grupie małych paciorków odmów „Najsłodsze Serce Maryi, bądź moim zbawieniem”.",
