"We adore You, O Christ, and we bless You, because by Your holy cross You have redeemed the world.": "Kłaniamy Ci się, Panie Jezu Chryste, i błogosławimy Tobie, że przez krzyż i mękę swoją świat odkupić raczyłeś.",
