"Every day is a new beginning. Start with one small prayer today.": "Każdy dzień to nowy początek. Zacznij dziś od jednej krótkiej modlitwy.",
"Pray now →": "Módl się teraz →",
"Choose what to track": "Wybierz, co zapisywać",
