"Your prayer log is private. It is kept only in this browser and is never sent anywhere.": "Twój dziennik modlitwy jest prywatny. Jest przechowywany tylko w tej przeglądarce i nigdy nie jest nigdzie wysyłany.",
"The last {n} weeks": "Ostatnie {n} tygodni",
