"Apologetics: the reasons behind the faith, and charitable answers to the questions and objections Catholics most often hear.": "Apologetyka: racje wiary i życzliwe odpowiedzi na pytania i zarzuty, które katolicy słyszą najczęściej.",
"Simple Words": "Prostymi słowami",
"Ten questions drawn at random from the saints, books, Church history, the Bible, and theology on Sanctify. Every quiz is different.": "Dziesięć losowych pytań o świętych, książki, historię Kościoła, Biblię i teologię w Sanctify. Każdy quiz jest inny.",
"Start the quiz": "Rozpocznij quiz",
