"Replace what’s on this device with the backup from {*}?": "Zastąpić dane na tym urządzeniu kopią zapasową z {*}?",
"follows the Roman Missal of 1962 and its calendar: the old feasts and seasons, Ember Days, the Latin Mass explained, and the fifteen mysteries of the Rosary. Its prayers are those of the Roman Catholic edition.": "opiera się na Mszale Rzymskim z 1962 roku i jego kalendarzu: dawne święta i okresy, Suche Dni, wyjaśnienie Mszy łacińskiej i piętnaście tajemnic różańca. Modlitwy są takie jak w wydaniu rzymskokatolickim.",
