"follows the Byzantine tradition, shared by the Ukrainian, Ruthenian, Melkite, Romanian, and other Greek Catholic Churches. The Maronite, Syro-Malabar, Chaldean, Armenian, Coptic, and other Eastern Catholic Churches have their own liturgies.": "opiera się na tradycji bizantyjskiej, wspólnej dla Kościołów greckokatolickich: ukraińskiego, rusińskiego, melchickiego, rumuńskiego i innych. Kościoły wschodniokatolickie maronicki, syromalabarski, chaldejski, ormiański, koptyjski i inne mają własne liturgie.",
