"Pray the ancient Jesus Prayer on a prayer rope, knot by knot, gathering the mind into the heart.": "Odmawiaj starożytną Modlitwę Jezusową na czotkach, węzeł po węźle, skupiając umysł w sercu.",
"{n}, {n}, or {n} knots": "{n}, {n} lub {n} węzłów",
"The prayers of the Byzantine tradition as illustrated cards, from O Heavenly King to It Is Truly Right.": "Modlitwy tradycji bizantyjskiej na ilustrowanych obrazkach, od „Królu Niebieski” do „Godne to jest”.",
