"See what’s new": "Zobacz nowości",
"Eight languages, a Settings page, the Community Wiki, and 75 more saints.": "Osiem języków, strona Ustawień, Wiki Społeczności i 75 nowych świętych.",
"Sanctify in eight languages, translated by hand: Spanish, Polish, French, Portuguese, Italian, German, Russian, and Ukrainian.": "Sanctify w ośmiu językach, tłumaczony ręcznie: hiszpańskim, polskim, francuskim, portugalskim, włoskim, niemieckim, rosyjskim i ukraińskim.",
"A Settings page for your language, edition, theme, text size, and data.": "Strona Ustawień: język, wydanie, motyw, rozmiar tekstu i dane.",
"{n} saints, {n} of them new in this release.": "{n} świętych, w tym {n} nowych w tej wersji.",
"The Community Wiki and News, each with its own page.": "Wiki Społeczności i Aktualności, każde na osobnej stronie.",
"Fuller profiles, with banners, badges, and your wiki contributions.": "Pełniejsze profile z banerami, odznakami i twoim wkładem w wiki.",
"Links to any page of Sanctify inside posts and wiki pages.": "Linki do dowolnej strony Sanctify we wpisach i na stronach wiki.",
"{n} color themes, with light and dark versions.": "Motywy kolorystyczne: {n}, w wersjach jasnych i ciemnych.",
"A clearer menu, and a friendly page for links that lead nowhere.": "Czytelniejsze menu i przyjazna strona dla linków, które prowadzą donikąd.",
"Free, without ads, for the greater glory of God.": "Za darmo, bez reklam, na większą chwałę Bożą.",
"Your badges show on your public profile.": "Twoje odznaki są widoczne w publicznym profilu.",
